"""
Screen 1 — Hardware detection.

Runs the hardware scan in a GLib thread so the UI stays responsive.
Shows a spinner while scanning, then populates a status table.
Blocks "Continue" if IOMMU is not active.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from .base import BasePage
from ..state import WizardState, DetectedHardware
from ..backend.hardware import run_hardware_scan
from typing import Callable


class DetectionScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="Hardware Detection", tag="detect")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "Hardware detection",
                "BulwarkOS is scanning your system. This takes a few seconds.",
            )
        )

        # Spinner shown while scanning
        self._spinner = Gtk.Spinner()
        self._spinner.set_size_request(48, 48)
        self._spinner.set_halign(Gtk.Align.CENTER)
        self._spinner.set_margin_top(24)
        self._spinner.set_margin_bottom(24)
        self._spinner.start()
        self._body.append(self._spinner)

        # Status group — hidden until scan completes
        self._status_group = Adw.PreferencesGroup()
        self._status_group.set_title("Detected hardware")
        self._status_group.set_visible(False)
        self._body.append(self._status_group)

        # IOMMU warning banner — hidden by default
        self._iommu_warn = Adw.Banner()
        self._iommu_warn.set_title(
            "IOMMU is not active. Reboot with intel_iommu=on (Intel) or "
            "amd_iommu=on (AMD) added to your kernel arguments, then re-run setup."
        )
        self._iommu_warn.set_revealed(False)
        self._body.append(self._iommu_warn)

        # GPU group-contamination warning
        self._gpu_warn = Adw.Banner()
        self._gpu_warn.set_title(
            "Your GPU shares an IOMMU group with other devices. GPU passthrough "
            "may require an ACS override patch and can reduce isolation guarantees."
        )
        self._gpu_warn.set_revealed(False)
        self._body.append(self._gpu_warn)

        # Buttons
        self._btn_row = self.make_button_row(
            back_label="Back",
            back_cb=lambda: self.go_to("back"),
            next_label="Continue",
            next_cb=self._on_continue,
        )
        self._body.append(self._btn_row)

        # Find and disable the Continue button until scan is done
        self._next_btn = self._btn_row.get_last_child()
        self._next_btn.set_sensitive(False)

        # Kick off background scan
        GLib.Thread.new("hw-scan", self._scan_thread, None)

    def _scan_thread(self, _data):
        """Runs in a background GLib thread — no GTK calls allowed here."""
        hw, nics, gpus = run_hardware_scan()
        # Schedule UI update on the main thread
        GLib.idle_add(self._on_scan_complete, hw, nics, gpus)

    def _on_scan_complete(self, hw: DetectedHardware, nics: list, gpus: list):
        """Called on the GTK main thread after the scan finishes."""
        # Store results in shared state
        self.state.hardware = hw
        self.state.nics = nics
        self.state.gpus = gpus

        # Stop spinner
        self._spinner.stop()
        self._spinner.set_visible(False)

        # Populate status rows
        rows = [
            ("CPU vendor",         hw.cpu_vendor.upper() if hw.cpu_vendor != "unknown" else "Unknown",
                                   "success" if hw.cpu_vendor != "unknown" else "error"),
            ("CPU model",          hw.cpu_model, ""),
            ("IOMMU",              "Active" if hw.iommu_active else "Not active",
                                   "success" if hw.iommu_active else "error"),
            ("IOMMU groups",       str(hw.iommu_groups) if hw.iommu_active else "—", ""),
            ("Network interfaces", str(len(nics)) + " passthrough-capable", ""),
            ("Discrete GPU(s)",    str(len(gpus)) + " detected" if gpus else "None detected", ""),
            ("Secure Boot",        "Enabled" if hw.secure_boot else "Disabled",
                                   "success" if hw.secure_boot else "warning"),
        ]

        for label, value, badge in rows:
            row = Adw.ActionRow()
            row.set_title(label)
            val_lbl = Gtk.Label(label=value)
            if badge == "success":
                val_lbl.add_css_class("success")
            elif badge == "error":
                val_lbl.add_css_class("error")
            elif badge == "warning":
                val_lbl.add_css_class("warning")
            row.add_suffix(val_lbl)
            self._status_group.add(row)

        self._status_group.set_visible(True)

        # Show banners where relevant
        if not hw.iommu_active:
            self._iommu_warn.set_revealed(True)

        gpu_contaminated = any(not g.group_isolated for g in gpus)
        if gpu_contaminated:
            self._gpu_warn.set_revealed(True)

        # Only allow Continue if IOMMU is active and we found at least one NIC
        if hw.iommu_active and len(nics) > 0:
            self._next_btn.set_sensitive(True)

        return GLib.SOURCE_REMOVE  # don't call again

    def _on_continue(self):
        self.go_to("nics")
